#include <iostream>
#include <vector>
using namespace std;

const int MOD = 1000000007;
vector<long long> fac;

long long powMod(long long a, long long b) {
    long long ans = 1;
    a %= MOD;
    while (b > 0) {
        if (b & 1) ans = ans * a % MOD;
        a = a * a % MOD;
        b >>= 1;
    }
    return ans;
}

long long comb(int n, int m) {
    if (m > n || m < 0) return 0;
    long long x = fac[n];
    long long y = fac[m] * fac[n - m] % MOD;
    return x * powMod(y, MOD - 2) % MOD;
}

int main() {
    int total, k;
    cin >> total >> k;

    if (total % 2 != 0) {
        cout << 0 << endl;
        return 0;
    }

    int n = total / 2;
    int maxN = total;  // 预处理到 total 即可
    fac.resize(maxN + 1);
